CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: validate_document_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_document_status_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.status = old.status then return new; end if;
  if not (
    (old.status = 'UPLOADING' and new.status in ('UPLOADED','UPLOAD_FAILED')) or
    (old.status = 'UPLOAD_FAILED' and new.status in ('UPLOADING','UPLOADED')) or
    (old.status = 'UPLOADED' and new.status in ('OCR_PROCESSING','OCR_FAILED')) or
    (old.status = 'OCR_FAILED' and new.status = 'OCR_PROCESSING') or
    (old.status = 'OCR_PROCESSING' and new.status in ('OCR_COMPLETED','REVIEW_REQUIRED','OCR_FAILED')) or
    (old.status = 'OCR_COMPLETED' and new.status = 'REVIEW_REQUIRED') or
    (old.status = 'REVIEW_REQUIRED' and new.status = 'READY_TO_SEND') or
    (old.status in ('READY_TO_SEND','SEND_FAILED','SENT') and new.status = 'SENDING') or
    (old.status = 'SENDING' and new.status in ('READY_TO_SEND','SENT','SEND_FAILED'))
  ) then
    raise exception 'invalid document status transition: % -> %', old.status, new.status using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION validate_document_status_transition(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.validate_document_status_transition() IS 'Validates document workflow transitions, review return, and explicit resend of completed documents.';


SET default_tablespace = '';

SET default_table_access_method = heap;

