-- Name: documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid DEFAULT auth.uid() NOT NULL,
    temporary_number text NOT NULL,
    template_code text DEFAULT 'FLOWER_V1'::text NOT NULL,
    source text DEFAULT 'REACT_NATIVE'::text NOT NULL,
    status text DEFAULT 'UPLOADING'::text NOT NULL,
    title text DEFAULT ''::text NOT NULL,
    original_image_path text,
    corrected_image_path text,
    thumbnail_path text,
    image_content_type text,
    image_size_bytes bigint,
    image_width integer,
    image_height integer,
    order_date text,
    orderer_name text DEFAULT ''::text NOT NULL,
    orderer_phone text DEFAULT ''::text NOT NULL,
    message text DEFAULT ''::text NOT NULL,
    product_alias text DEFAULT ''::text NOT NULL,
    product_name text DEFAULT ''::text NOT NULL,
    amount numeric(12,0),
    payment_method text DEFAULT ''::text NOT NULL,
    delivery_at text,
    recipient_name text DEFAULT ''::text NOT NULL,
    recipient_phone text DEFAULT ''::text NOT NULL,
    address text DEFAULT ''::text NOT NULL,
    remarks text DEFAULT ''::text NOT NULL,
    partner_id uuid,
    external_reference text,
    revision bigint DEFAULT 1 NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewed_at timestamp with time zone,
    sent_at timestamp with time zone,
    archived_at timestamp with time zone,
    CONSTRAINT documents_amount_check CHECK (((amount IS NULL) OR (amount >= (0)::numeric))),
    CONSTRAINT documents_image_height_check CHECK (((image_height IS NULL) OR (image_height > 0))),
    CONSTRAINT documents_image_size_check CHECK (((image_size_bytes IS NULL) OR (image_size_bytes >= 0))),
    CONSTRAINT documents_image_width_check CHECK (((image_width IS NULL) OR (image_width > 0))),
    CONSTRAINT documents_revision_check CHECK ((revision > 0)),
    CONSTRAINT documents_source_check CHECK ((source = ANY (ARRAY['REACT_NATIVE'::text, 'PC_WEB'::text, 'MIGRATION'::text]))),
    CONSTRAINT documents_status_check CHECK ((status = ANY (ARRAY['UPLOADING'::text, 'UPLOADED'::text, 'OCR_PROCESSING'::text, 'OCR_COMPLETED'::text, 'REVIEW_REQUIRED'::text, 'READY_TO_SEND'::text, 'SENDING'::text, 'SENT'::text, 'SEND_FAILED'::text, 'UPLOAD_FAILED'::text, 'OCR_FAILED'::text])))
);


