    "vendorName" text DEFAULT ''::text NOT NULL,
    "customerPm" text DEFAULT ''::text NOT NULL,
    "customerPmoCount" integer DEFAULT 0 NOT NULL,
    "vendorPm" text DEFAULT ''::text NOT NULL,
    "vendorPmoCount" integer DEFAULT 0 NOT NULL,
    "projectGrade" public."ProjectGrade" DEFAULT 'B'::public."ProjectGrade" NOT NULL,
    timezone text DEFAULT 'Asia/Seoul'::text NOT NULL,
    "staleBusinessDays" integer DEFAULT 3 NOT NULL,
