--
-- Name: recurring_meeting_reservations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.recurring_meeting_reservations (
    id text NOT NULL,
    "projectId" text NOT NULL,
    "roomId" text NOT NULL,
    "applicantId" text NOT NULL,
    "patternType" public."RecurringMeetingPattern" NOT NULL,
    "patternDetail" jsonb NOT NULL,
    "startMinutes" integer NOT NULL,
    "endMinutes" integer NOT NULL,
    "periodStart" date NOT NULL,
    "periodEnd" date NOT NULL,
    purpose text NOT NULL,
    status public."RecurringMeetingStatus" DEFAULT 'PENDING'::public."RecurringMeetingStatus" NOT NULL,
    "reviewedBy" text,
    "reviewedAt" timestamp(3) without time zone,
    "rejectReason" text,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone NOT NULL,
    CONSTRAINT recurring_meeting_minutes_check CHECK ((("startMinutes" >= 0) AND ("endMinutes" <= 1440) AND ("endMinutes" > "startMinutes"))),
    CONSTRAINT recurring_meeting_period_check CHECK (("periodEnd" >= "periodStart")),
    CONSTRAINT recurring_meeting_review_check CHECK ((((status = 'PENDING'::public."RecurringMeetingStatus") AND ("reviewedBy" IS NULL) AND ("reviewedAt" IS NULL) AND ("rejectReason" IS NULL)) OR ((status = 'APPROVED'::public."RecurringMeetingStatus") AND ("reviewedBy" IS NOT NULL) AND ("reviewedAt" IS NOT NULL) AND ("rejectReason" IS NULL)) OR ((status = 'REJECTED'::public."RecurringMeetingStatus") AND ("reviewedBy" IS NOT NULL) AND ("reviewedAt" IS NOT NULL) AND ("rejectReason" IS NOT NULL)) OR (status = 'CANCELLED'::public."RecurringMeetingStatus")))
);


